//! The OKF (Open Knowledge Format) wiki: Markdown pages with a YAML frontmatter whose values are
//! JSON literals (one `key: value` per line, so it is valid YAML and needs no YAML parser).
//!
//! Machine-written blocks sit between `<!-- pup:begin NAME -->` and `<!-- pup:end NAME -->` and
//! are regenerated by `wiki-finalize`. The LLM writes only between `<!-- llm:begin -->` and
//! `<!-- llm:end -->`, the `description`/`tags` frontmatter values, and `topics/*.md`.

pub mod check;
pub mod export;
pub mod facts;
pub mod finalize;
pub mod plan;
pub mod render;

use anyhow::{bail, Context, Result};
use serde_json::Value;
use std::path::{Path, PathBuf};

pub const LLM_BEGIN: &str = "<!-- llm:begin -->";
pub const LLM_END: &str = "<!-- llm:end -->";
pub const STATE_PATH: &str = ".pup/state.json";
pub const TYPES: &[&str] = &["event", "event-type", "market", "topic", "index", "log"];

#[derive(Debug, Clone, PartialEq)]
pub struct Page {
    pub frontmatter: Vec<(String, Value)>,
    pub body: String,
}

impl Page {
    pub fn new(fm: Vec<(&str, Value)>, body: String) -> Self {
        Self {
            frontmatter: fm.into_iter().map(|(k, v)| (k.to_string(), v)).collect(),
            body,
        }
    }

    pub fn parse(text: &str) -> Result<Self> {
        let rest = text
            .strip_prefix("---\n")
            .context("missing frontmatter start")?;
        let (head, body) = rest
            .split_once("\n---\n")
            .context("missing frontmatter end")?;
        let mut frontmatter = Vec::new();
        for line in head.lines().filter(|l| !l.trim().is_empty()) {
            let (k, v) = line
                .split_once(':')
                .with_context(|| format!("frontmatter line without key: {line}"))?;
            let v: Value = serde_json::from_str(v.trim())
                .with_context(|| format!("frontmatter `{k}` is not a JSON literal"))?;
            frontmatter.push((k.trim().to_string(), v));
        }
        Ok(Self {
            frontmatter,
            body: body.trim_start_matches('\n').to_string(),
        })
    }

    pub fn read(path: &Path) -> Result<Self> {
        Self::parse(
            &std::fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?,
        )
        .with_context(|| format!("parse {}", path.display()))
    }

    pub fn render(&self) -> String {
        let mut s = String::from("---\n");
        for (k, v) in &self.frontmatter {
            s.push_str(&format!("{k}: {}\n", serde_json::to_string(v).unwrap()));
        }
        s.push_str("---\n\n");
        s.push_str(self.body.trim_end());
        s.push('\n');
        s
    }

    pub fn write(&self, path: &Path) -> Result<()> {
        if let Some(p) = path.parent() {
            std::fs::create_dir_all(p)?;
        }
        std::fs::write(path, self.render())?;
        Ok(())
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.frontmatter
            .iter()
            .find(|(k, _)| k == key)
            .map(|(_, v)| v)
    }

    pub fn get_str(&self, key: &str) -> &str {
        self.get(key).and_then(Value::as_str).unwrap_or_default()
    }

    /// Text of the LLM block(s).
    pub fn llm(&self) -> String {
        llm_blocks(&self.body).join("\n")
    }

    /// Replaces a machine block's content, appending the block at the end if it is missing.
    pub fn set_block(&mut self, name: &str, content: &str) {
        let (begin, end) = (
            format!("<!-- pup:begin {name} -->"),
            format!("<!-- pup:end {name} -->"),
        );
        let block = format!("{begin}\n{}\n{end}", content.trim());
        match (self.body.find(&begin), self.body.find(&end)) {
            (Some(a), Some(b)) if b > a => self.body.replace_range(a..b + end.len(), &block),
            _ => {
                self.body = format!("{}\n\n{block}\n", self.body.trim_end());
            }
        }
    }
}

pub fn llm_blocks(body: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = body;
    while let Some(a) = rest.find(LLM_BEGIN) {
        let after = &rest[a + LLM_BEGIN.len()..];
        let Some(b) = after.find(LLM_END) else { break };
        out.push(after[..b].trim().to_string());
        rest = &after[b + LLM_END.len()..];
    }
    out
}

pub fn walk_md(root: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(dir) = stack.pop() {
        let Ok(rd) = std::fs::read_dir(&dir) else {
            continue;
        };
        for e in rd.flatten() {
            let p = e.path();
            let name = e.file_name();
            if name.to_string_lossy().starts_with('.') {
                continue;
            }
            if p.is_dir() {
                stack.push(p);
            } else if p.extension().is_some_and(|x| x == "md") {
                out.push(p);
            }
        }
    }
    out.sort();
    out
}

pub fn rel(root: &Path, p: &Path) -> String {
    p.strip_prefix(root)
        .unwrap_or(p)
        .to_string_lossy()
        .replace('\\', "/")
}

/// Published JSON from a local directory (`public/data`) or a Pages URL.
pub struct Source {
    base: String,
    client: Option<reqwest::blocking::Client>,
}

impl Source {
    pub fn new(base: &str) -> Result<Self> {
        let base = base.trim_end_matches('/').to_string();
        let client = if base.starts_with("http") {
            Some(crate::http::client()?)
        } else {
            None
        };
        Ok(Self { base, client })
    }

    pub fn get(&self, rel: &str) -> Result<Option<Value>> {
        match &self.client {
            Some(c) => {
                // Pages answers 503 now and then under a burst of requests; retry with backoff.
                let url = format!("{}/{rel}", self.base);
                let mut last = None;
                for attempt in 0..5u32 {
                    if attempt > 0 {
                        std::thread::sleep(std::time::Duration::from_secs(2u64.pow(attempt)));
                    }
                    match c.get(&url).send() {
                        Ok(r) if r.status() == reqwest::StatusCode::NOT_FOUND => return Ok(None),
                        Ok(r) if r.status().is_success() => return Ok(Some(r.json()?)),
                        Ok(r) if r.status().is_server_error() || r.status().as_u16() == 429 => {
                            last = Some(anyhow::anyhow!("GET {url}: HTTP {}", r.status()));
                        }
                        Ok(r) => bail!("GET {url}: HTTP {}", r.status()),
                        Err(e) => last = Some(anyhow::Error::new(e).context(format!("GET {url}"))),
                    }
                }
                Err(last.unwrap_or_else(|| anyhow::anyhow!("GET {url} failed")))
            }
            None => {
                let p = Path::new(&self.base).join(rel);
                if !p.exists() {
                    return Ok(None);
                }
                Ok(Some(
                    serde_json::from_slice(&std::fs::read(&p)?)
                        .with_context(|| format!("parse {}", p.display()))?,
                ))
            }
        }
    }
}

pub fn today_jst() -> chrono::NaiveDate {
    let jst = chrono::FixedOffset::east_opt(9 * 3600).unwrap();
    chrono::Utc::now().with_timezone(&jst).date_naive()
}

/// Wiki-relative paths.
pub fn event_path(kind: &str, date: &str) -> String {
    format!("events/{kind}/{date}.md")
}
pub fn type_path(kind: &str) -> String {
    format!("event-types/{kind}.md")
}
pub fn market_path(id: &str) -> String {
    format!("markets/{id}.md")
}

/// Relative link from page `from` to page `to` (both wiki-relative).
pub fn link(from: &str, to: &str) -> String {
    let depth = from.matches('/').count();
    format!("{}{to}", "../".repeat(depth))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn roundtrips_frontmatter_and_blocks() {
        let mut p = Page::new(
            vec![("type", json!("event")), ("tags", json!(["a"]))],
            format!("# t\n\n{LLM_BEGIN}\nhello\n{LLM_END}\n"),
        );
        p.set_block("facts", "x");
        p.set_block("facts", "y");
        let q = Page::parse(&p.render()).unwrap();
        assert_eq!(q.get_str("type"), "event");
        assert_eq!(q.llm(), "hello");
        assert!(q
            .body
            .contains("<!-- pup:begin facts -->\ny\n<!-- pup:end facts -->"));
        assert_eq!(q.body.matches("pup:begin facts").count(), 1);
    }

    #[test]
    fn links_are_relative() {
        assert_eq!(
            link("events/fomc/2025-09-17.md", "markets/spx.md"),
            "../../markets/spx.md"
        );
        assert_eq!(link("index.md", "markets/spx.md"), "markets/spx.md");
    }
}
